examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    HStack(spacing: theme.spacing.space2) {
        MonarchSelectField(
            {{toolbar.filter}},
            selection: $area,
            options: [MonarchSelectOption({{toolbar.filter}}, value: "all")],
            labelVisibility: .hidden
        )
        .frame(maxWidth: 160)
        Spacer()
        ShareLink(item: Self.events.map { "\($0.time),\($0.actor),\($0.action),\($0.target ?? "")" }.joined(separator: "\n")) {
            Text({{toolbar.export}})
        }
        .buttonStyle(.monarch(.secondary, size: .sm))
    }
    // Five narrow columns that fit a phone, so none is cut off; the Details link is the last.
    Group {
        Grid(alignment: .topLeading, horizontalSpacing: theme.spacing.space1, verticalSpacing: 0) {
            GridRow {
                ForEach(["Time", "Actor", "Action", "Target", "Details"], id: \.self) { title in
                    Text(title == "Details" ? "" : title)
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                        .frame(width: Self.columnWidths[title], alignment: .leading)
                }
            }
            .padding(.vertical, theme.spacing.space2)
            .padding(.horizontal, theme.spacing.space2)
            .background(theme.colors.bgSubtle)
            ForEach(Self.events) { event in
                Divider().gridCellUnsizedAxes(.horizontal)
                GridRow {
                    Text(Self.timeText(event.time))
                        .foregroundStyle(theme.colors.textMuted)
                        .frame(width: Self.columnWidths["Time"], alignment: .leading)
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text(event.actor).fontWeight(.medium)
                        if let kind = event.kind { MonarchBadge(Self.kindLabel(kind)).lineLimit(1).minimumScaleFactor(0.6) }
                    }
                    .frame(width: Self.columnWidths["Actor"], alignment: .leading)
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text(event.action)
                        if let source = event.source { MonarchBadge(source).lineLimit(1).minimumScaleFactor(0.6) }
                    }
                    .frame(width: Self.columnWidths["Action"], alignment: .leading)
                    Text(event.target ?? "—")
                        .frame(width: Self.columnWidths["Target"], alignment: .leading)
                    Button("Details") {}
                        .buttonStyle(.plain)
                        .underline()
                        .lineLimit(1)
                        .minimumScaleFactor(0.7)
                        .frame(width: Self.columnWidths["Details"], alignment: .leading)
                }
                .monarchTextStyle(.caption)
                .padding(.vertical, theme.spacing.space3)
                .padding(.horizontal, theme.spacing.space2)
            }
        }
    }
    MonarchLoadMore(
        hasMore: true,
        loadedCount: Self.events.count,
        labels: MonarchLoadMoreLabels(count: { count, _ in "Showing \(count) events" })
    ) {
        // Fetch the next page with the cursor of the last event.
    }
}
.frame(maxWidth: .infinity)

examples.setupTemplate:
struct AuditEvent: Identifiable, Sendable {
    let id: String
    let actor: String
    let kind: String?
    let action: String
    let target: String?
    let source: String?
    let time: Date
}

private static let columnWidths: [String: CGFloat] = ["Time": 62, "Actor": 60, "Action": 66, "Target": 48, "Details": 46]

private static let events = [
    AuditEvent(
        id: {{events.0.id}}, actor: {{events.0.actor}}, kind: nil, action: {{events.0.action}}, target: {{events.0.target}},
        source: nil, time: {{events.0.time|date}}
    ),
    AuditEvent(
        id: {{events.1.id}}, actor: {{events.1.actor}}, kind: nil, action: {{events.1.action}}, target: nil,
        source: nil, time: {{events.1.time|date}}
    ),
    AuditEvent(
        id: {{events.2.id}}, actor: {{events.2.actor}}, kind: {{events.2.kind}}, action: {{events.2.action}}, target: {{events.2.target}},
        source: {{events.2.source}}, time: {{events.2.time|date}}
    ),
    AuditEvent(
        id: {{events.3.id}}, actor: {{events.3.actor}}, kind: {{events.3.kind}}, action: {{events.3.action}}, target: {{events.3.target}},
        source: nil, time: {{events.3.time|date}}
    ),
]

/// The kind of actor as a label: "automation" is Automation, "api" is API.
private nonisolated static func kindLabel(_ kind: String) -> String { kind == "api" ? "API" : kind.capitalized }

private nonisolated static func timeText(_ date: Date) -> String {
    {
        let locale = Locale(identifier: {{locale}})
        let zone = TimeZone(identifier: {{timeZone}}) ?? .gmt
        let day = date.formatted(Date.FormatStyle(date: .abbreviated, time: .omitted, locale: locale, timeZone: zone))
        let clock = date.formatted(
            Date.FormatStyle(locale: locale, timeZone: zone).hour(.twoDigits(amPM: .omitted)).minute(.twoDigits).second(.twoDigits)
        )
        return day + ", " + clock
    }()
}

@Environment(\.monarchTheme) private var theme
@State private var area = "all"

